// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(new __InvMutHandleStub()), address(new __InvMutHandleStub())); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        // The deployer is the owner; transferring ownership to any nonzero actor must succeed.
        vm.prank(address(this));
        try c.transferOwnership(actor) {
            assertTrue(c.owner() == actor, "owner transfer must set the new owner");
        } catch {
            assertTrue(false, "owner must be able to transfer ownership");
        }
    }
}
